{
  "annotator_prompt": [
    {
      "kind": "add",
      "field": "button_center_xy",
      "description": "Most recently reliably localized world-frame [x,y] center of the stationary gray button press surface, in metres. Initialize to null until an available calibrated image permits reliable localization. Update using clear views available in the current cycle, accounting for the press surface's elevation above the table. Otherwise retain the previous value through occlusion and cube manipulation. Use only evidence available by this cycle, never later views. e.g. [-0.19, -0.16]",
      "value_type": "world_coordinate"
    }
  ],
  "policy_prompt_for_memory": [
    {
      "kind": "add",
      "field": "button_center_xy",
      "description": "Initialize to null. Whenever this cycle's calibrated images clearly expose the gray button press surface and permit reliable localization, record its world-frame center [x,y] in metres, accounting for its elevation above the table. Otherwise retain the incoming value, including through occlusion and cube manipulation. Do not substitute the TCP position, the white base's image center, or a guessed location. e.g. [-0.19, -0.16]"
    }
  ],
  "policy_prompt_for_action": [
    {
      "modify_from": "Use table-plane projection for the target and account for cube height when locating its center. Refine with the wrist view; do not confuse its image center with the TCP projection.",
      "modify_to": "For a calibrated homogeneous image pixel p, form the world ray with origin C=-R^T t and direction d=R^T K^-1 p. Intersect it with the physical plane of the feature being localized: for plane z=h, use C+((h-C_z)/d_z)d. Use the table plane for the target ring. For a resting cube, localize the center of its visible top face on its top-face plane, approximately z=0.04 m; the recovered x,y is its pickup center. Do not project that pixel onto the table or use the resting-cube top-plane height for a held cube. Localize the gray button press-surface center accounting for its elevation using button geometry and calibrated views, not by projecting its cap pixel onto the table or substituting the white base's image center. Prefer a clear reliable current view; otherwise use button_center_xy for the button. Never substitute another object's location. If the button cannot be localized and button_center_xy is null, use an open-hand clearance motion to expose it before attempting button approach. Refine with the wrist view; do not confuse its image center with the TCP projection. Recognition of a completed motion allows the next manipulation step but does not establish that achieved TCP x,y equals the intended object center; independently localize that center when constructing the next waypoint."
    },
    {
      "modify_from": "At release_retracted with placements_completed < N, similarly make a dedicated open-hand alignment at z=0.15 m above that same cube, now on the target; do not return to its original location.",
      "modify_to": "At release_retracted with placements_completed < N, make a dedicated open-hand alignment at z=0.15 m above the height-corrected current center of that same cube, now on the target; do not return to its original location or substitute the achieved withdrawal TCP x,y."
    },
    {
      "modify_from": "At target_hover, lower at the target center to commanded z=0.005 m and open.",
      "modify_to": "At target_hover, re-estimate the target-ring center and lower at that center to commanded z=0.005 m and open, correcting lateral tracking error during descent rather than copying achieved hover TCP x,y."
    },
    {
      "modify_from": "At release_retracted with placements_completed >= N, move above the button center at z=0.15 m with open fingers and orientation [-3.1416,0,0]. At button_hover, close the empty gripper while maintaining alignment and approximately this height. At button_closed, descend at the button center to commanded z=0.0075 m with fingers closed. At button_pressed, retract to z=0.15 m with fingers closed.",
      "modify_to": "At release_retracted with placements_completed >= N, move above the reliably localized current button center, or button_center_xy when the current view is unreliable, at z=0.15 m with open fingers and orientation [-3.1416,0,0]. At button_hover, close the empty gripper at that independently localized button center x,y and nominal z=0.15 m, correcting any hover tracking offset. At button_closed, descend at the independently localized button center to commanded z=0.0075 m with fingers closed; do not substitute achieved hover TCP x,y. At button_pressed, retract at the button center x,y to z=0.15 m with fingers closed."
    },
    {
      "modify_from": "Every waypoint must differ from the current TCP position by at least 2 mm. For a gripper-only change or otherwise necessary near-identical hover alignment, add a small upward displacement, about 3–5 mm, while keeping the intended x,y.",
      "modify_to": "Construct the center-corrected waypoint first, then apply the 2 mm minimum positional-displacement safeguard. If its lateral or vertical correction already supplies at least 2 mm of displacement from the current TCP, do not add an upward offset. For a gripper-only change or otherwise necessary near-identical hover alignment below that threshold, add a small upward displacement, about 3–5 mm, while keeping the intended center x,y. Preserve the explicit rule for omitting a redundant target-hover motion at cube_lifted."
    }
  ],
  "refused": ""
}
